document.addEventListener('DOMContentLoaded', () => { document.querySelectorAll('[data-directory-select]').forEach((selectRoot) => { const key = selectRoot.dataset.directorySelect; const input = document.querySelector(`[data-directory-select-input="${key}"]`); const label = selectRoot.querySelector('[data-directory-select-label]'); const search = selectRoot.querySelector('[data-directory-select-search]'); const options = Array.from(selectRoot.querySelectorAll('[data-value]')); options.forEach((option) => { option.addEventListener('click', () => { if (input) input.value = option.dataset.value || ''; if (label) { label.innerHTML = option.innerHTML; } options.forEach((item) => item.classList.toggle('is-selected', item === option)); }); }); search?.addEventListener('input', () => { const needle = search.value.trim().toLowerCase(); options.forEach((option) => { const haystack = (option.dataset.label || option.textContent || '').toLowerCase(); option.classList.toggle('d-none', needle !== '' && ! haystack.includes(needle)); }); }); }); });